"""Locations for results generated by the current financial calculation pipeline."""

from pathlib import Path
import re


RESULTS_VERSION = "v2"
DEFAULT_RESULTS_DIRECTORY = Path("data/results") / RESULTS_VERSION


def model_directory(extraction_model=None, analysis_model=None):
    name = f"{extraction_model or 'default'}_{analysis_model or 'default'}"
    return re.sub(r"_+", "_", re.sub(r"[^a-zA-Z0-9_-]", "_", name)).strip("_")
